function showCodex(){state.screen='codex';const box=document.createElement('div');box.className='screen overlay';box.innerHTML=`<section class="panel"><h2>Codex · fidélité cinéma</h2><div class="grid2"><div><h3>Règles</h3>${D.fidelityRules.map(x=>`<p>• ${x}</p>`).join('')}<h3>Contenu coupé — hors campagne principale</h3>${D.cutContent.map(x=>`<p>— ${x}</p>`).join('')}</div><div><h3>Références de vérification</h3>${D.references.map(r=>`<p><b>${r.id} · ${r.title}</b><br/><small>${r.use}</small></p>`).join('')}<h3>Indices trouvés</h3><p>${[...new Set(Object.values(loadProgress()).flatMap(x=>x?.clues||[]))].join(' · ')||'Aucun pour le moment'}</p><button class="btn primary" id="back">Retour</button></div></div></section>`;app.append(box);$('#back').onclick=()=>{box.remove();state.screen='menu'}}
