function startCampaign(id,index,room=0,resume=false){state.campaign=id;state.index=clamp(index,0,sceneList(id).length-1);loadScene(room,resume)}
function weaponDef(){return D.weapons[state.scene?.weapon]||D.weapons.none}
function maxHpForActor(){return state.scene.actor==='Upgrade Predator'?165:state.scene.predator?125:100}
function deterministic(seed){let h=2166136261;for(const ch of seed){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0)/4294967295}
function mirrorSummary(p=loadProgress()){const events={};for(const [cid,c] of Object.entries(D.campaigns))for(const s of c.scenes){events[s.event]??={};events[s.event][cid]=true}const done=p._mirrorEvents||{};let mastered=0;for(const [id,sides] of Object.entries(events)){const v=done[id]||{};if((!sides.human||v.human)&&(!sides.predator||v.predator))mastered++}return{mastered,available:Object.keys(events).length}}
function markMirrorEvent(progress,event,campaign){progress._mirrorEvents=progress._mirrorEvents||{};const before=progress._mirrorEvents[event]||{},next={...before,[campaign]:true};progress._mirrorEvents[event]=next;const hasHuman=sceneList('human').some(s=>s.event===event),hasPredator=sceneList('predator').some(s=>s.event===event),wasMastered=(!hasHuman||before.human)&&(!hasPredator||before.predator),mastered=(!hasHuman||next.human)&&(!hasPredator||next.predator);if(mastered&&!wasMastered)emitHost('mirror-complete',{event,campaign,mastery:mirrorSummary(progress)});return mastered}
function roomPhases(){return currentRoom()?.phases||['advance']}function currentPhase(){const p=roomPhases();return p[clamp(state.objectivePhase,0,p.length-1)]||p[0]}function hazardDef(){return D.environmentHazards?.[currentRoom()?.hazard]||null}function hazardZone(){const r=currentRoom(),lanes=state.scene?.lanes||D.locations[state.scene?.location]?.lanes||1,seed=deterministic(`${r?.id||'room'}:hazard`);return{x:innerWidth*(.38+.28*((seed*11)%1)),lane:Math.floor(seed*lanes)%lanes,radius:82}}
function cycleSquadOrder(next){if(state.scene?.predator)return state.squadOrder;const orders=D.gameplay.squadOrders||['follow','focus','hold'];state.squadOrder=next&&orders.includes(next)?next:orders[(orders.indexOf(state.squadOrder)+1)%orders.length];emitHost('squad-order',{campaign:state.campaign,scene:state.scene?.id,order:state.squadOrder,cohesion:Math.round(state.cohesion)});msg(`Escouade · ${state.squadOrder}`,.9);saveProgress();return state.squadOrder}
function enemyRole(type,i,boss=false){if(boss)return'boss';if(/dog|bullies/.test(type||''))return'charger';if(/upgrade|fugitive/.test(type||''))return i%2?'flanker':'charger';if(isRanged(type))return i%3===0?'suppressor':i%3===1?'flanker':'assault';return'assault'}
function roomWaveTotal(){return Number(currentRoom()?.reinforcementWaves||0)}function spawnReinforcementWave(reason='clear'){const total=roomWaveTotal();if(state.roomWave>=total)return false;state.roomWave++;const r=currentRoom(),count=Math.max(1,Math.min(3,1+Math.floor((r?.tacticalIntensity||1)/2))),base=state.enemies.length;for(let i=0;i<count;i++)state.enemies.push(makeEnemy(state.scene.enemy||'enemy',base+i,base+count,false));state.stats.waves++;const cached=state.roomCache.get(state.roomIndex);if(cached)cached.wave=state.roomWave;saveProgress();emitHost('reinforcement-wave',{scene:state.scene.id,room:state.roomIndex,wave:state.roomWave,total,reason});msg(`Renforts · vague ${state.roomWave}/${total}`,1.2);return true}
function advanceObjectivePhase(reason='auto'){const phases=roomPhases();if(state.objectivePhase>=phases.length-1)return false;state.objectivePhase++;const cached=state.roomCache.get(state.roomIndex);if(cached)cached.phaseIndex=state.objectivePhase;saveProgress();emitHost('objective-phase',{scene:state.scene.id,room:state.roomIndex,phase:currentPhase(),phaseIndex:state.objectivePhase,reason});msg(`Objectif · ${currentPhase()}`,1);return true}
function masterySnapshot(){const p=loadProgress(),mirror=mirrorSummary(p);const result={mirror,scenes:0,gradeS:0,secondary:0};for(const id of ['human','predator'])for(const r of Object.values(p[id]?.records||{})){result.scenes++;if(r.grade==='S')result.gradeS++;result.secondary+=r.secondary||0}return result}
function enemyHp(type,boss=false){if(boss)return /upgrade/.test(type)?390:/fugitive/.test(type)?280:250;if(/upgrade/.test(type))return 175;if(/fugitive/.test(type))return 135;if(/predator-dog/.test(type))return 82;if(/ship|jet/.test(type))return 110;if(/bullies/.test(type))return 42;return 62}
function isRanged(type){return /stargazer|soldier|cartel|loonie|human-hunters|final-humans|boarders|upgrade|fugitive|ship|jet|mixed-hunt|quinn/.test(type||'')&&!/dog/.test(type||'')}
function isPredType(kind){return /predator|upgrade|fugitive|hound|dog/i.test(kind||'')}
function makeEnemy(type,i,count,boss=false){const lanes=state.scene.lanes||D.locations[state.scene.location].lanes||1,actual=type==='mixed-hunt'?(i%3===0?'upgrade':i%2?'stargazer':'human-hunters'):type==='final-humans'?(i%3===0?'quinn':i%3===1?'casey':'predator-dog'):type;const hp=enemyHp(actual,boss),armor=/upgrade/.test(actual)?(boss?125:65):0;return{x:innerWidth*(.43+.49*(i+1)/(count+1)),lane:i%lanes,hp,maxHp:hp,armor,maxArmor:armor,type:actual,dir:-1,cd:350+deterministic(state.scene.id+state.roomIndex+i)*900,shotCd:500+deterministic('s'+state.scene.id+i)*900,boss,phase:1,chargeCd:1500,taggedT:0,aiRole:enemyRole(actual,i,boss),morale:100,telegraph:0,telegraphKind:null}}
function buildRoomState(roomIndex){const r=route()[roomIndex],final=roomIndex===route().length-1,s=state.scene;let count=Math.min(8,r.enemyBudget||0);let boss=false;if(final&&s.goal==='boss'){count=1;boss=true}if(final&&s.goal==='scripted-loss'&&/upgrade-boss|final-humans/.test(s.enemy||''))count=Math.max(1,Math.min(3,s.enemies||1));if(final&&s.goal==='survive'&&s.enemies)count=Math.max(1,Math.min(3,s.enemies));const enemies=[];for(let i=0;i<count;i++)enemies.push(makeEnemy(s.enemy||'enemy',i,count,boss));const picks=[];const seed=deterministic(`${s.id}:${roomIndex}`);if(s.location!=='orbit'&&seed>.28){const kind=s.predator?(seed>.72?'energy-cell':'medkit'):(seed>.72?'ammo':'medkit');picks.push({kind,x:innerWidth*(.38+.38*((seed*7)%1)),lane:Math.floor(seed*(s.lanes||1))%(s.lanes||1),taken:false})}return{enemies,pickups:picks,cleared:false,alerted:false,secondaryComplete:false,phaseIndex:0,wave:0,wavesTotal:r.reinforcementWaves||0,hazard:r.hazard||null}}
function persistRoom(){if(!state.scene||!state.roomCache)return;const old=state.roomCache.get(state.roomIndex)||{};state.roomCache.set(state.roomIndex,{...old,enemies:state.enemies,pickups:state.pickups,cleared:state.enemies.every(e=>e.hp<=0)&&state.roomWave>=roomWaveTotal(),alerted:state.alerted,secondaryComplete:old.secondaryComplete||false,phaseIndex:state.objectivePhase,wave:state.roomWave,wavesTotal:roomWaveTotal(),hazard:currentRoom()?.hazard||null})}
function coverPositions(){const r=currentRoom(),s=state.scene,lanes=s?.lanes||D.locations[s?.location]?.lanes||1,n=r?.coverNodes||0,out=[];for(let i=0;i<n;i++){const seed=deterministic(`${r.id}:cover:${i}`);out.push({x:innerWidth*(.22+.58*((seed*9+i*.31)%1)),lane:i%lanes})}return out}
