function damagePlayer(amount){const p=state.player,s=state.scene;if(!p||p.invuln>0)return 0;let dmg=amount;if(state.guard&&nearCover()){dmg*=.52;state.stats.guards++}if(!s.predator&&state.squadOrder==='hold'&&Array.isArray(s.companions)&&s.companions.length)dmg*=.9;if(s.predator&&state.cloak)dmg*=.35;if(p.armor>0){const absorb=Math.min(p.armor,dmg*.62);p.armor-=absorb;dmg-=absorb}p.hp-=dmg;p.lastDamage=performance.now();state.stats.damage+=dmg;if(s.predator)state.momentum=clamp(state.momentum-dmg*.35,0,100);else state.cohesion=clamp(state.cohesion-dmg*.22,0,100);burst(p.x,laneY(p.lane,s.lanes||1)-35,'#ff7b6b');return dmg}
