addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space'].includes(e.code))e.preventDefault();if((e.code==='Enter'||e.code==='KeyE')&&state.briefing){action();return}if(e.code==='Escape'){if(state.screen==='play')menu();else if(state.screen==='codex')menu();return}if(e.code==='Space'){attack();return}if(e.code==='KeyE'){action();return}if(e.code==='KeyR'){reload();return}if(e.code==='KeyF'){pulse();return}if(e.code==='KeyT'){takedown();return}if(e.code==='KeyG'){cycleSquadOrder();return}if(e.code==='ShiftLeft'||e.code==='ShiftRight'){evade();return}if((e.code==='ArrowUp'||e.code==='KeyW'||e.code==='KeyZ')&&state.screen==='play'){shiftLane(-1);return}if((e.code==='ArrowDown'||e.code==='KeyS')&&state.screen==='play'){shiftLane(1);return}if(e.code==='KeyC'&&state.scene?.predator)state.cloak=!state.cloak;if(e.code==='KeyV'&&state.scene?.predator)state.vision=!state.vision;if(e.code==='KeyM'&&state.screen==='play')chapterMenu();if(e.code==='KeyP'&&state.screen==='play'&&!state.briefing&&!state.card)state.paused=!state.paused;state.keys.add(e.code)});addEventListener('keyup',e=>state.keys.delete(e.code));
function touchBind(){document.querySelectorAll('[data-key]').forEach(b=>{const code=b.dataset.key;const down=e=>{e.preventDefault();if(code==='Space')attack();else if(code==='KeyE')action();else if(code==='KeyC'&&state.scene?.predator)state.cloak=!state.cloak;else if(code==='KeyV'&&state.scene?.predator)state.vision=!state.vision;else if(code==='KeyT')takedown();else if(code==='KeyG')cycleSquadOrder();else if(code==='ShiftLeft')evade();else if(code==='ArrowUp')shiftLane(-1);else if(code==='ArrowDown')shiftLane(1);else state.keys.add(code)};const up=e=>{e.preventDefault();state.keys.delete(code)};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up)})}
